// Shared shapes for app/core.js and app/ui.js (checked by `tsc --noEmit`, see tsconfig.json).
// Ambient declarations: no imports or exports, so every name here is global in both files.

/** One row of data/words.json: a deck word in Anki rank order. */
interface Word { rank: number; bg: string; en: string; pos: string; forms: string; learned?: boolean }

/** One practice sentence from data/sentences.json. */
interface Sentence {
  id: string; bg: string; nl: string; en: string;
  nl_alt: string[]; bg_alt: string[]; en_alt: string[];
  /** accepted with a "looser translation" note (D-014) */
  nl_loose?: string[]; en_loose?: string[];
  /** Bulgarian answers accepted only for the English prompt: the other "you" form (D-018) */
  bg_alt_en?: string[];
  lemmas: string[]; max_rank: number | null; tags: string[]; source: string; grammar?: string[];
}

interface GrammarTable { headers: string[]; rows: string[][] }
interface GrammarCard { id: string; stage: number; title: string; intro: string; table: GrammarTable; notes?: string[]; examples?: string[] }
interface GrammarData { version: number; pronouns: string[]; cards: GrammarCard[]; paradigms: any }

/** window.TRAKIA_DATA, generated by tools/build_data.py into app/data.js. */
interface TrakiaData { words: Word[]; sentences: Sentence[]; grammar: GrammarData; learnedRank: number }

/** Learner settings (DEFAULTS in ui.js, persisted in localStorage). */
interface Settings {
  rank: number; tolerance: number; newPerSession: number; maxDue: number;
  directions: string; newOrder: string; lang: string; typoPct: number; bagOfWords: boolean;
  almostPolicy: string; almostFreePasses: number; retention: number; maxInterval: number; stage: number;
  strictPunct: boolean; strictYi: boolean; stripAccents: boolean; strictForms: boolean; translit: boolean; theme: string;
  /** cards in a row on one keyboard before switching (D-021); 1 alternates every card */
  dirRun: number;
  /** moving background (D-023): 'none' | 'fire' | 'video', a direct video URL, and the overlay opacity 0–90 */
  wallpaper: string; wallpaperUrl: string; wallpaperDim: number;
  freeSize?: number; fsrs?: Partial<FsrsOptions>;
}

interface FsrsOptions { retention: number; learningSteps: number[]; relearningSteps: number[]; maxInterval: number; fuzz: boolean }

/** Per-card progress record (key `<sentence id>|<direction>`), see D-001 and D-002. */
interface ProgressRecord {
  box: number; due: number; reps: number; lapses: number; streak: number; last: number;
  s?: number; d?: number; state?: 'learning' | 'review' | 'relearning'; step?: number; rating?: number;
  almosts?: number; orders?: number; lastRule?: string;
}

type Progress = Record<string, ProgressRecord>;

/** What `$()` in ui.js returns: an element with the form-control fields the UI reads and writes.
 *  Looser than the DOM's per-tag interfaces, but it keeps field names and value types checked. */
interface AppElement extends HTMLElement {
  value: string; checked: boolean; disabled: boolean; selectedIndex: number; options: HTMLOptionsCollection;
  open: boolean; files: FileList | null; selectionStart: number | null; selectionEnd: number | null;
  rows: HTMLCollectionOf<HTMLTableRowElement>; min: string; max: string; step: string;
  placeholder: string; width: number; height: number; getContext: HTMLCanvasElement['getContext'];
  _t?: ReturnType<typeof setTimeout>; _bars?: { x: number; w: number; d: any; tot: number }[];
}

interface Window { TRAKIA_DATA: TrakiaData; TrakiaCore: any; XLSX?: any }
/** SheetJS, loaded on demand from cdnjs for .xlsx imports. */
declare const XLSX: any;
